import { z } from 'zod';
import raw from '@data/gas_kntt.json';
import { molarMass } from '@/chemistry/formula';
import { dopri5 } from '@/core/ode';
import {
  loadDataset,
  LocalizedTextSchema,
  ReviewStatusSchema,
  type Source,
} from '@/core/data/dataset';

/**
 * Vật lí 12 KNTT Chương II "Khí lí tưởng", Bài 9–12: Boyle (pV = const), Charles (V/T = const), the
 * equation of state pV/T = const and pV = nRT, and the kinetic model p = ⅔μĒđ, Ēđ = 3/2 kT. Every
 * constant and table is the textbook's (data/gas_kntt.json, generated by
 * scripts/data/gen_gas_kntt.py; review pending, DATA_REVIEW VL12-GAS-1). Molar masses come from
 * the standard atomic weights of data/elements.json (the book prints none).
 */
const GasSchema = z.object({
  id: z.string().min(1),
  formula: z.string().min(1),
  name: LocalizedTextSchema,
  review_status: ReviewStatusSchema,
});
const ExtraSchema = z.object({
  constants: z.object({ R: z.number(), k: z.number(), N_A: z.number() }),
  standard: z.object({ p: z.number(), V: z.number(), T: z.number() }),
  kelvin_offset: z.literal(273),
  boyle_table: z.array(z.object({ V_cm3: z.number(), p_1e5Pa: z.number() })),
  charles_table: z.array(z.object({ t_C: z.number(), T_K: z.number(), V_mL: z.number() })),
  validity: z.object({ p_max: z.number(), T_min: z.number() }),
  examples: z.array(z.looseObject({ id: z.string(), lesson: z.number(), page: z.number() })),
});

const dataset = loadDataset('gas_kntt', GasSchema, raw);
const extra = ExtraSchema.parse(raw);

export type Gas = z.infer<typeof GasSchema>;
export const GASES: readonly Gas[] = dataset.items;
export const GAS_SOURCE: Source = dataset.source;
/** The book's rounded R (J/(mol·K)) and N_A (1/mol); k = R/N_A as the book defines it (tr. 49). */
export const R = extra.constants.R;
export const N_A = extra.constants.N_A;
export const K_B = R / N_A;
/** The value the book prints for k (1,38·10⁻²³ J/K). */
export const K_PRINTED = extra.constants.k;
export const STANDARD = extra.standard;
/** The book converts with T = t + 273 throughout Chương II. */
export const K_OFFSET_BOOK = extra.kelvin_offset;
export const K_OFFSET_EXACT = 273.15;
/** Where the book says the laws were found (tr. 44): p not above 10⁵ Pa, T not below 200 K. */
export const VALIDITY = extra.validity;
export const EXAMPLES = extra.examples;

export const gas = (id: string): Gas => {
  const g = GASES.find((x) => x.id === id);
  if (!g) throw new Error(`no gas ${id}`);
  return g;
};

/* ───────── States and processes (Bài 9–11) ───────── */

/** p (Pa), V (m³), T (K). */
export interface GasState {
  p: number;
  V: number;
  T: number;
}
export type Quantity = keyof GasState;
export const PROCESSES = ['isothermal', 'isobaric', 'isochoric', 'general'] as const;
export type Process = (typeof PROCESSES)[number];

/** The quantity each process keeps (the general change keeps none). */
export const HELD: Record<Process, Quantity | null> = {
  isothermal: 'T',
  isobaric: 'p',
  isochoric: 'V',
  general: null,
};
/** Quantities of state 2 the learner may ask for in each process. */
export const UNKNOWNS: Record<Process, readonly Quantity[]> = {
  isothermal: ['p', 'V'],
  isobaric: ['V', 'T'],
  isochoric: ['p', 'T'],
  general: ['p', 'V', 'T'],
};

const ok = (s: GasState) => ([s.p, s.V, s.T].every((x) => Number.isFinite(x) && x > 0) ? s : null);

/**
 * State 2 from state 1 and what is given of state 2: the held quantity equals state 1's, the
 * unknown follows from p₁V₁/T₁ = p₂V₂/T₂ (11.1). Null when a state is not physical.
 */
export function solveState(
  process: Process,
  unknown: Quantity,
  s1: GasState,
  given: GasState,
): GasState | null {
  if (!ok(s1) || !UNKNOWNS[process].includes(unknown)) return null;
  const s2 = { ...given };
  const held = HELD[process];
  if (held) s2[held] = s1[held];
  const c = (s1.p * s1.V) / s1.T;
  if (unknown === 'p') s2.p = (c * s2.T) / s2.V;
  else if (unknown === 'V') s2.V = (c * s2.T) / s2.p;
  else s2.T = (s2.p * s2.V) / c;
  return ok(s2);
}

export interface Path {
  /** Points [V, p] from state 1 to state 2 on the p–V diagram. */
  points: [number, number][];
  /** The intermediate state of Hình 11.1 for a general change (isothermal, then isobaric). */
  mid: GasState | null;
}

/** The path the lesson draws: one of the three simple processes, or Hình 11.1's two steps. */
export function processPath(process: Process, s1: GasState, s2: GasState, n = 64): Path {
  const isotherm = (a: GasState, vEnd: number) =>
    Array.from({ length: n + 1 }, (_, i): [number, number] => {
      const v = a.V + ((vEnd - a.V) * i) / n;
      return [v, (a.p * a.V) / v];
    });
  if (process === 'isothermal') return { points: isotherm(s1, s2.V), mid: null };
  if (process === 'isobaric' || process === 'isochoric')
    return {
      points: [
        [s1.V, s1.p],
        [s2.V, s2.p],
      ],
      mid: null,
    };
  const mid: GasState = { p: s2.p, V: (s1.p * s1.V) / s2.p, T: s1.T };
  return { points: [...isotherm(s1, mid.V), [s2.V, s2.p]], mid };
}

/**
 * Independent check of a general change: integrate Hình 11.1's two steps as ODEs with DOPRI5 — on
 * the isotherm dp/dV = −p/V from V₁ to V₁', then at constant p dT/dV = T/V from V₁' to V₂ — and
 * return the end state, which must be the one `solveState` found.
 */
export function integratedTwoSteps(s1: GasState, s2: GasState): GasState {
  const vMid = (s1.p * s1.V) / s2.p;
  // DOPRI5 runs forward only: V = v0 + s·(v1 − v0) for s from 0 to 1 (the volume may shrink).
  const leg = (rate: (v: number, y: number) => number, y0: number, v0: number, v1: number) => {
    if (v0 === v1) return y0;
    const r = dopri5(
      (s, y, dy) => {
        dy[0] = rate(v0 + s * (v1 - v0), y[0] ?? 0) * (v1 - v0);
      },
      [y0],
      0,
      1,
      { rtol: 1e-12, atol: 1e-14 },
    );
    return r.y[0] ?? NaN;
  };
  const p = leg((v, y) => -y / v, s1.p, s1.V, vMid);
  const T = leg((v, y) => y / v, s1.T, vMid, s2.V);
  return { p, V: s2.V, T };
}

/** True when the state is where the book says Boyle's and Charles's laws were checked. */
export const withinBookRange = (s: GasState) => s.p <= VALIDITY.p_max && s.T >= VALIDITY.T_min;

/** n = pV/(RT) (11.2). */
export const moles = (s: GasState) => (s.p * s.V) / (R * s.T);

/** The worked example of Bài 10 (tr. 43): the volume grows by dV from t₁ to t₂ at constant p. */
export function charlesFromIncrease(t1: number, t2: number, dV: number, offset = K_OFFSET_BOOK) {
  const T1 = t1 + offset;
  const T2 = t2 + offset;
  const V1 = (dV * T1) / (T2 - T1);
  return { T1, T2, V1, V2: V1 + dV };
}

/* ───────── The book's experiments (Bảng 9.1, 10.1) ───────── */

export const BOYLE_ROWS = extra.boyle_table.map((r) => ({
  V: r.V_cm3 * 1e-6,
  p: r.p_1e5Pa * 1e5,
  /** p·V (J), computed by the app as the book asks (tr. 39). */
  pV: r.V_cm3 * 1e-6 * r.p_1e5Pa * 1e5,
}));
export const CHARLES_ROWS = extra.charles_table.map((r) => ({
  t: r.t_C,
  T: r.T_K,
  V: r.V_mL * 1e-6,
  /** V/T (m³/K), computed by the app as the book asks (tr. 43). */
  VT: (r.V_mL * 1e-6) / r.T_K,
}));

/** Mean of the values and the largest relative distance of one value from it. */
export function spread(values: readonly number[]) {
  const mean = values.reduce((a, v) => a + v, 0) / values.length;
  const worst = Math.max(...values.map((v) => Math.abs(v - mean) / mean));
  return { mean, worst };
}

/* ───────── Molecules (Bài 12) ───────── */

/** Molar mass (kg/mol) from the standard atomic weights. */
export const molarMassOf = (g: Gas) => molarMass(g.formula) / 1000;
/** Mass of one molecule (kg): m = M/N_A. */
export const moleculeMass = (g: Gas) => molarMassOf(g) / N_A;
/** Ēđ = 3/2 kT (12.3). */
export const meanKineticEnergy = (T: number) => 1.5 * K_B * T;
/** √(v̄²) from ½m v̄² = 3/2 kT: the root-mean-square speed (tr. 51). */
export const rmsSpeed = (g: Gas, T: number) => Math.sqrt((3 * K_B * T) / moleculeMass(g));
/** μ = N/V from p = ⅔μĒđ = μkT. */
export const numberDensity = (p: number, T: number) => p / (K_B * T);
/** p = ⅓μm v̄² (12.1). */
export const kineticPressure = (mu: number, m: number, v2: number) => (mu * m * v2) / 3;
